mapper.select:
SELECT id, user_id, group_id, storage_path, taken_date, location_name, city, province, country, description, is_deleted, created_at
FROM photo
WHERE id = #{id}

SELECT p.id,
       p.storage_path,
       DATE_FORMAT(p.taken_date, '%Y-%m-%d') AS taken_date,
       p.country,
       COALESCE(pr.provence, p.province) AS provence,
       p.city,
       p.location_name,
       p.description
FROM photo p
LEFT JOIN provence pr ON pr.id = p.province
WHERE p.group_id = #{groupId}
  AND p.is_deleted = 0
  AND p.taken_date IS NOT NULL


    AND p.taken_date >= #{startDate}


    AND p.taken_date <= #{endDate}


    AND COALESCE(pr.provence, p.province) = #{provence}


    AND p.city = #{city}

ORDER BY p.taken_date DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT p.id,
       p.storage_path,
       DATE_FORMAT(p.taken_date, '%Y-%m-%d') AS taken_date,
       p.country,
       COALESCE(pr.provence, p.province) AS provence,
       p.city,
       p.location_name,
       p.description
FROM photo p
LEFT JOIN provence pr ON pr.id = p.province
WHERE p.user_id = #{userId}
  AND p.is_deleted = 0
  AND p.taken_date IS NOT NULL


    AND p.taken_date >= #{startDate}


    AND p.taken_date <= #{endDate}


    AND COALESCE(pr.provence, p.province) = #{provence}


    AND p.city = #{city}

ORDER BY p.taken_date DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM photo p
LEFT JOIN provence pr ON pr.id = p.province
WHERE p.group_id = #{groupId}
  AND (p.is_deleted IS NULL OR p.is_deleted = 0)
  AND p.taken_date IS NOT NULL


    AND p.taken_date >= #{startDate}


    AND p.taken_date <= #{endDate}


    AND COALESCE(pr.provence, p.province) = #{provence}


    AND p.city = #{city}

SELECT COUNT(*)
FROM photo p
LEFT JOIN provence pr ON pr.id = p.province
WHERE p.user_id = #{userId}
  AND (p.is_deleted IS NULL OR p.is_deleted = 0)
  AND p.taken_date IS NOT NULL


    AND p.taken_date >= #{startDate}


    AND p.taken_date <= #{endDate}


    AND COALESCE(pr.provence, p.province) = #{provence}


    AND p.city = #{city}

SELECT id FROM photo
WHERE group_id = #{groupId}
  AND (is_deleted IS NULL OR is_deleted = 0)

SELECT id FROM photo
WHERE user_id = #{userId}
  AND (is_deleted IS NULL OR is_deleted = 0)

SELECT id FROM photo
WHERE group_id = #{groupId}
  AND (is_deleted IS NULL OR is_deleted = 0)
  AND taken_date BETWEEN #{startDate} AND #{endDate}

SELECT id FROM photo
WHERE user_id = #{userId}
  AND (is_deleted IS NULL OR is_deleted = 0)
  AND taken_date BETWEEN #{startDate} AND #{endDate}
